BEGIN TRANSACTION;
CREATE TABLE allowances (
	id INTEGER NOT NULL, 
	allowance_id VARCHAR NOT NULL, 
	employee_id INTEGER NOT NULL, 
	pay_period_id INTEGER NOT NULL, 
	allowance_type VARCHAR NOT NULL, 
	amount FLOAT NOT NULL, 
	effective_date DATE NOT NULL, 
	reference_code VARCHAR NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(employee_id) REFERENCES employees (id), 
	FOREIGN KEY(pay_period_id) REFERENCES pay_periods (id)
);
CREATE TABLE approvals (
	id INTEGER NOT NULL, 
	approval_id VARCHAR NOT NULL, 
	payroll_input_id INTEGER NOT NULL, 
	approver_name VARCHAR NOT NULL, 
	approver_role VARCHAR NOT NULL, 
	decision VARCHAR NOT NULL, 
	comments VARCHAR, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(payroll_input_id) REFERENCES payroll_inputs (id)
);
CREATE TABLE audit_logs (
	id INTEGER NOT NULL, 
	log_id VARCHAR NOT NULL, 
	entity_name VARCHAR NOT NULL, 
	record_id VARCHAR NOT NULL, 
	action VARCHAR NOT NULL, 
	actor_role VARCHAR NOT NULL, 
	actor_name VARCHAR NOT NULL, 
	old_values VARCHAR, 
	new_values VARCHAR, 
	reason VARCHAR, 
	timestamp DATETIME NOT NULL, 
	PRIMARY KEY (id)
);
CREATE TABLE deductions (
	id INTEGER NOT NULL, 
	deduction_id VARCHAR NOT NULL, 
	employee_id INTEGER NOT NULL, 
	pay_period_id INTEGER NOT NULL, 
	deduction_type VARCHAR NOT NULL, 
	amount FLOAT NOT NULL, 
	effective_date DATE NOT NULL, 
	reference_code VARCHAR NOT NULL, 
	leave_record_id INTEGER, 
	PRIMARY KEY (id), 
	FOREIGN KEY(employee_id) REFERENCES employees (id), 
	FOREIGN KEY(pay_period_id) REFERENCES pay_periods (id), 
	FOREIGN KEY(leave_record_id) REFERENCES leave_records (id)
);
CREATE TABLE employee_allowance_eligibilities (
	id INTEGER NOT NULL, 
	employee_id INTEGER NOT NULL, 
	allowance_type VARCHAR NOT NULL, 
	is_eligible BOOLEAN NOT NULL, 
	effective_start DATE NOT NULL, 
	effective_end DATE, 
	PRIMARY KEY (id), 
	FOREIGN KEY(employee_id) REFERENCES employees (id)
);
CREATE TABLE employees (
	id INTEGER NOT NULL, 
	employee_id VARCHAR NOT NULL, 
	name VARCHAR NOT NULL, 
	email VARCHAR NOT NULL, 
	department VARCHAR, 
	designation VARCHAR, 
	bank_account VARCHAR, 
	tax_id VARCHAR, 
	basic_salary FLOAT NOT NULL, 
	employment_status VARCHAR NOT NULL, 
	pay_group_id INTEGER NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (email), 
	FOREIGN KEY(pay_group_id) REFERENCES pay_groups (id)
);
CREATE TABLE exceptions (
	id INTEGER NOT NULL, 
	exception_id VARCHAR NOT NULL, 
	payroll_input_id INTEGER, 
	validation_rule_id INTEGER, 
	employee_id INTEGER NOT NULL, 
	issue_type VARCHAR NOT NULL, 
	description VARCHAR, 
	status VARCHAR NOT NULL, 
	severity VARCHAR NOT NULL, 
	source_entity VARCHAR, 
	source_record_id VARCHAR, 
	resolution_notes VARCHAR, 
	resolved_by VARCHAR, 
	resolved_at DATETIME, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(payroll_input_id) REFERENCES payroll_inputs (id), 
	FOREIGN KEY(validation_rule_id) REFERENCES validation_rules (id), 
	FOREIGN KEY(employee_id) REFERENCES employees (id)
);
CREATE TABLE leave_records (
	id INTEGER NOT NULL, 
	leave_id VARCHAR NOT NULL, 
	employee_id INTEGER NOT NULL, 
	pay_period_id INTEGER NOT NULL, 
	leave_type VARCHAR NOT NULL, 
	start_date DATE NOT NULL, 
	end_date DATE NOT NULL, 
	days FLOAT NOT NULL, 
	approval_status VARCHAR NOT NULL, 
	is_unpaid BOOLEAN NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(employee_id) REFERENCES employees (id), 
	FOREIGN KEY(pay_period_id) REFERENCES pay_periods (id)
);
CREATE TABLE pay_groups (
	id INTEGER NOT NULL, 
	group_code VARCHAR NOT NULL, 
	group_name VARCHAR NOT NULL, 
	pay_frequency VARCHAR NOT NULL, 
	max_period_hours FLOAT NOT NULL, 
	standard_hours FLOAT NOT NULL, 
	PRIMARY KEY (id)
);
CREATE TABLE pay_periods (
	id INTEGER NOT NULL, 
	period_code VARCHAR NOT NULL, 
	start_date DATE NOT NULL, 
	end_date DATE NOT NULL, 
	payment_date DATE, 
	status VARCHAR NOT NULL, 
	PRIMARY KEY (id)
);
CREATE TABLE payroll_exports (
	id INTEGER NOT NULL, 
	export_id VARCHAR NOT NULL, 
	pay_period_id INTEGER NOT NULL, 
	file_name VARCHAR NOT NULL, 
	file_format VARCHAR NOT NULL, 
	record_count INTEGER NOT NULL, 
	total_amount FLOAT NOT NULL, 
	export_status VARCHAR NOT NULL, 
	exported_by VARCHAR NOT NULL, 
	exported_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(pay_period_id) REFERENCES pay_periods (id)
);
CREATE TABLE payroll_inputs (
	id INTEGER NOT NULL, 
	payroll_input_id VARCHAR NOT NULL, 
	employee_id INTEGER NOT NULL, 
	pay_period_id INTEGER NOT NULL, 
	basic_salary FLOAT NOT NULL, 
	overtime_amount FLOAT NOT NULL, 
	allowance_total FLOAT NOT NULL, 
	deduction_total FLOAT NOT NULL, 
	unpaid_leave_deduction FLOAT NOT NULL, 
	net_pay FLOAT NOT NULL, 
	status VARCHAR NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(employee_id) REFERENCES employees (id), 
	FOREIGN KEY(pay_period_id) REFERENCES pay_periods (id)
);
CREATE TABLE time_entries (
	id INTEGER NOT NULL, 
	time_id VARCHAR NOT NULL, 
	employee_id INTEGER NOT NULL, 
	pay_period_id INTEGER NOT NULL, 
	work_date DATE NOT NULL, 
	hours_worked FLOAT NOT NULL, 
	approval_status VARCHAR NOT NULL, 
	submission_ref VARCHAR NOT NULL, 
	corrects_time_entry_id INTEGER, 
	PRIMARY KEY (id), 
	FOREIGN KEY(employee_id) REFERENCES employees (id), 
	FOREIGN KEY(pay_period_id) REFERENCES pay_periods (id), 
	FOREIGN KEY(corrects_time_entry_id) REFERENCES time_entries (id)
);
CREATE TABLE validation_rules (
	id INTEGER NOT NULL, 
	rule_code VARCHAR NOT NULL, 
	rule_name VARCHAR NOT NULL, 
	description VARCHAR, 
	severity VARCHAR NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	PRIMARY KEY (id)
);
CREATE UNIQUE INDEX ix_pay_groups_group_code ON pay_groups (group_code);
CREATE UNIQUE INDEX ix_pay_periods_period_code ON pay_periods (period_code);
CREATE UNIQUE INDEX ix_validation_rules_rule_code ON validation_rules (rule_code);
CREATE UNIQUE INDEX ix_audit_logs_log_id ON audit_logs (log_id);
CREATE UNIQUE INDEX ix_employees_employee_id ON employees (employee_id);
CREATE UNIQUE INDEX ix_payroll_exports_export_id ON payroll_exports (export_id);
CREATE UNIQUE INDEX ix_time_entries_time_id ON time_entries (time_id);
CREATE UNIQUE INDEX ix_leave_records_leave_id ON leave_records (leave_id);
CREATE UNIQUE INDEX ix_allowances_allowance_id ON allowances (allowance_id);
CREATE UNIQUE INDEX ix_payroll_inputs_payroll_input_id ON payroll_inputs (payroll_input_id);
CREATE UNIQUE INDEX ix_deductions_deduction_id ON deductions (deduction_id);
CREATE UNIQUE INDEX ix_exceptions_exception_id ON exceptions (exception_id);
CREATE UNIQUE INDEX ix_approvals_approval_id ON approvals (approval_id);
COMMIT;
