INSERT INTO "validation_rules" VALUES(1,'RULE-BANK-001','Missing Bank Account Validation','Flags active employees missing required bank account numbers before payroll disbursement.','HIGH',1);
INSERT INTO "validation_rules" VALUES(2,'RULE-TAX-001','Missing Tax ID Validation','Flags active employees missing statutory tax identification numbers.','HIGH',1);
INSERT INTO "validation_rules" VALUES(3,'RULE-TIME-DUP-001','Duplicate Time Entry Submission','Flags duplicate time submissions sharing identical submission reference codes or employee and date.','HIGH',1);
INSERT INTO "validation_rules" VALUES(4,'RULE-TIME-EXC-001','Excessive Working Hours / Outliers','Flags approved hours exceeding the pay group''s maximum period hours or single-shift outliers > 16h.','HIGH',1);
INSERT INTO "validation_rules" VALUES(5,'RULE-ALW-DUP-001','Duplicate Allowance Validation','Flags duplicate allowances with identical reference codes or duplicate grants of single-grant allowances.','HIGH',1);
INSERT INTO "validation_rules" VALUES(6,'RULE-TIME-UNAPP-001','Unapproved Time Entries Validation','Flags unapproved or pending time entries within a pay period, preventing premature inclusion or export.','HIGH',1);
INSERT INTO "validation_rules" VALUES(7,'RULE-LEV-DUP-001','Duplicate Leave Deduction Validation','Flags unpaid leave deductions that are applied multiple times for the same leave record or period.','HIGH',1);
INSERT INTO "validation_rules" VALUES(8,'RULE-PAY-RECON-001','Payroll Totals Reconciliation Validation','Flags arithmetic discrepancies between net pay and calculated component totals (basic + overtime + allowances - deductions - unpaid leave).','HIGH',1);
